from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Sum of square(x) for every x in xs, with squares computed in parallel.

    The squares are computed on a thread pool of `workers` threads. The result
    is identical for every worker count and equals sum(x * x for x in xs).
    An empty list gives 0. Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_single_element() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_large_values_no_overflow() -> None:
    big = 10**12
    assert sum_squares([big, big]) == 2 * big * big


def test_default_matches_sequential() -> None:
    xs = list(range(-50, 51))
    assert sum_squares(xs) == sum(x * x for x in xs)


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-500, 500))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 5, 64])
def test_more_workers_than_elements(workers: int) -> None:
    assert sum_squares([2, 3], workers=workers) == 13
    assert sum_squares([], workers=workers) == 0


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs, workers=3)
    assert xs == [3, -1, 2]


def test_repeatable() -> None:
    xs = [5, -4, 3, 2, 1] * 100
    results = {sum_squares(xs, workers=w) for w in (1, 2, 4, 7) for _ in range(3)}
    assert results == {sum(x * x for x in xs)}


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2, 3], workers=workers)
